(function(root){'use strict';
const enc=new TextEncoder(),dec=new TextDecoder(),ITER=600000,AAD=enc.encode('an-web-vault:1');
const b64=a=>{let s='';for(let i=0;i<a.length;i+=32768)s+=String.fromCharCode(...a.subarray(i,i+32768));return btoa(s)};
const bytes=s=>{if(typeof s!=='string'||s.length>75000000||!/^[A-Za-z0-9+/]*={0,2}$/.test(s))throw Error('Tệp sao lưu không hợp lệ.');return Uint8Array.from(atob(s),c=>c.charCodeAt(0))};
function url(raw){raw=String(raw||'').trim();if(!raw)throw Error('Nhập đường link website.');if(!/^[a-z][a-z0-9+.-]*:/i.test(raw))raw='https://'+raw;let u;try{u=new URL(raw)}catch{throw Error('Đường link không hợp lệ.')}if(!['https:','http:'].includes(u.protocol)||!u.hostname||u.username||u.password)throw Error('Chỉ lưu link http:// hoặc https://, không kèm thông tin đăng nhập.');return u.href}
function canonical(raw){const u=new URL(url(raw));u.hostname=u.hostname.toLowerCase();if(u.pathname==='/')u.pathname='';return u.href.replace(/\/$/,'')}
const fold=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase();
function entry(input,old){const now=new Date().toISOString(),link=url(input.url),title=String(input.title||'').trim()||new URL(link).hostname;return{id:old?.id||crypto.randomUUID(),title:title.slice(0,160),url:link,category:String(input.category||'Chưa phân loại').trim().slice(0,70)||'Chưa phân loại',notes:String(input.notes||'').slice(0,5000),tags:(Array.isArray(input.tags)?input.tags:String(input.tags||'').split(',')).map(x=>String(x).trim().slice(0,40)).filter(Boolean).filter((x,i,a)=>a.indexOf(x)===i).slice(0,30),repo:input.repo?url(input.repo):'',color:['blue','mint','violet','peach','rose','sand'].includes(input.color)?input.color:'blue',status:['active','building','paused'].includes(input.status)?input.status:'active',favorite:!!input.favorite,created:old?.created||now,updated:now,opened:old?.opened||null,deleted:old?.deleted||null}}
function validData(d){if(!d||d.version!==1||!Array.isArray(d.entries)||!d.settings||![5,15,30,60].includes(d.settings.idleMinutes))throw Error('Dữ liệu sao lưu không đúng định dạng.');const ids=new Set();for(const e of d.entries){if(!e||typeof e.id!=='string'||ids.has(e.id)||typeof e.title!=='string'||!e.title||e.title.length>160||typeof e.category!=='string'||typeof e.notes!=='string'||!Array.isArray(e.tags)||e.tags.some(x=>typeof x!=='string')||typeof e.favorite!=='boolean'||!['active','building','paused'].includes(e.status)||!['blue','mint','violet','peach','rose','sand'].includes(e.color)||typeof e.created!=='string'||!Number.isFinite(Date.parse(e.created))||!Number.isFinite(Date.parse(e.updated))||e.deleted!==null&&!Number.isFinite(Date.parse(e.deleted))||e.opened!==null&&!Number.isFinite(Date.parse(e.opened)))throw Error('Có website không hợp lệ trong bản sao.');if(url(e.url)!==e.url||e.repo&&url(e.repo)!==e.repo)throw Error('Có đường link không hợp lệ trong bản sao.');ids.add(e.id)}return d}
function envelope(e){if(e?.format==='an-web-vault-open'&&e.version===1){validData(e.data);return e}if(!e||e.format!=='an-web-vault'||e.version!==1||e.kdf!=='PBKDF2-SHA256'||!Number.isInteger(e.iterations)||e.iterations<100000||e.iterations>1200000||bytes(e.salt).length!==16||bytes(e.iv).length!==12||bytes(e.ciphertext).length<16)throw Error('Tệp không phải bản sao kho website được hỗ trợ.');return e}
async function derive(password,salt,iterations=ITER){const material=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function seal(data,key,salt,iterations=ITER){validData(data);if(key===null)return{format:'an-web-vault-open',version:1,data:structuredClone(data)};const iv=crypto.getRandomValues(new Uint8Array(12)),ciphertext=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:AAD},key,enc.encode(JSON.stringify(data)));return{format:'an-web-vault',version:1,kdf:'PBKDF2-SHA256',iterations,salt:b64(salt),iv:b64(iv),ciphertext:b64(new Uint8Array(ciphertext))}}
async function create(data,password){if(password.length<8)throw Error('Mật khẩu cần ít nhất 8 ký tự.');const salt=crypto.getRandomValues(new Uint8Array(16)),key=await derive(password,salt);return{key,salt,iterations:ITER,envelope:await seal(data,key,salt)}}
async function unlock(e,password){envelope(e);if(e.format==='an-web-vault-open')return{data:structuredClone(e.data),key:null,salt:null,iterations:0};const salt=bytes(e.salt),key=await derive(password,salt,e.iterations);let plain;try{plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:bytes(e.iv),additionalData:AAD},key,bytes(e.ciphertext))}catch{throw Error('Mật khẩu chưa đúng hoặc bản sao đã bị hỏng.')}const data=validData(JSON.parse(dec.decode(plain)));return{data,key,salt,iterations:e.iterations}}
function fresh(){return{version:1,entries:[],settings:{idleMinutes:15}}}
function add(data,input,id){const old=id?data.entries.find(e=>e.id===id):null;if(id&&!old)throw Error('Website này không còn tồn tại.');const value=entry(input,old);if(data.entries.some(e=>e.id!==id&&canonical(e.url)===canonical(value.url)))throw Error('Link này đã có trong kho hoặc thùng rác. Hãy sửa hoặc khôi phục mục cũ.');if(old)data.entries[data.entries.indexOf(old)]=value;else data.entries.push(value);return value}
function merge(current,incoming){validData(incoming);const result=structuredClone(current),keys=new Set(result.entries.map(e=>canonical(e.url)));let added=0;for(const e of incoming.entries){const c=canonical(e.url);if(keys.has(c))continue;const copy={...e,id:crypto.randomUUID()};result.entries.push(copy);keys.add(c);added++}return{data:result,added,skipped:incoming.entries.length-added}}

function syncToken(){return [...crypto.getRandomValues(new Uint8Array(32))].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function createOpen(data){return{key:null,salt:null,iterations:0,envelope:await seal(data,null,null,0)}}
async function readWithKey(e,key){envelope(e);if(e.format==='an-web-vault-open')return structuredClone(e.data);return validData(JSON.parse(dec.decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:bytes(e.iv),additionalData:AAD},key,bytes(e.ciphertext)))))}
const api={syncToken,createOpen,readWithKey,url,canonical,fold,entry,validData,envelope,derive,seal,create,unlock,fresh,add,merge,ITER};if(typeof module!=='undefined')module.exports=api;else root.VaultCore=api;
})(typeof window!=='undefined'?window:globalThis);
